<?php require 'config/bootstrap.php'; require_login(); $pdo=db(); $err=[];
if($_SERVER['REQUEST_METHOD']==='POST'){ csrf_check();
 if(($_POST['do']??'')==='profile'){ $n=trim($_POST['name']??''); $m=strtolower(trim($_POST['email']??'')); if($n==='')$err[]='Name required.'; if(!filter_var($m,FILTER_VALIDATE_EMAIL))$err[]='Valid email required.';
  if(!$err){ $s=$pdo->prepare('SELECT id FROM users WHERE email=? AND id<>?');$s->execute([$m,uid()]); if($s->fetch())$err[]='Email already in use.'; }
  if(!$err){ $pdo->prepare('UPDATE users SET name=?,email=? WHERE id=?')->execute([$n,$m,uid()]); $_SESSION['name']=$n; flash('Profile updated.'); header('Location: settings.php'); exit; } }
 else { $s=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([uid()]); if(!password_verify($_POST['current']??'',(string)$s->fetchColumn()))$err[]='Current password is wrong.'; if(strlen($_POST['new']??'')<8)$err[]='New password must be at least 8 characters.';
  if(!$err){ $pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($_POST['new'],PASSWORD_DEFAULT),uid()]); session_regenerate_id(true); log_act('password_changed'); flash('Password changed.'); header('Location: settings.php'); exit; } } }
$u=$pdo->prepare('SELECT name,email FROM users WHERE id=?');$u->execute([uid()]);$u=$u->fetch(); page_head('Settings'); ?><h1 class="h3 mb-3">Settings</h1><?php foreach($err as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?>
<div class="row g-3"><div class="col-md-6"><form method="post" class="cardx"><?=csrf_field()?><input type="hidden" name="do" value="profile"><h2 class="h6">Profile</h2><label class="form-label">Name</label><input class="form-control" name="name" required value="<?=e($u['name'])?>"><label class="form-label mt-2">Email</label><input class="form-control" type="email" name="email" required value="<?=e($u['email'])?>"><button class="btn btn-primary mt-3">Save</button></form></div>
<div class="col-md-6"><form method="post" class="cardx"><?=csrf_field()?><input type="hidden" name="do" value="password"><h2 class="h6">Change password</h2><label class="form-label">Current</label><input class="form-control" type="password" name="current" required><label class="form-label mt-2">New (min 8)</label><input class="form-control" type="password" name="new" minlength="8" required><button class="btn btn-primary mt-3">Change</button></form></div></div>
